        typeFactory = TypeFactory.defaultInstance();
    }

    // Mocking helper to create a JavaType with specific behaviors
    private JavaType mockType(Class<?> rawClass, boolean isArray, boolean isConcrete, boolean isTreeNode) {
        JavaType t = mock(JavaType.class);
        when(t.getRawClass()).thenReturn(rawClass);
        when(t.isArrayType()).thenReturn(isArray);
        when(t.isConcrete()).thenReturn(isConcrete);

        // Handle the TreeNode logic via isAssignableFrom check on the raw class
        if (isTreeNode) {
