            // We simulate this by ensuring the rawClass provided is a subclass of TreeNode
            // Or we can mock the behavior if the code were different, but here it depends on the class itself.
        }
        return t;
    }

    // Helper to mock the "getContentType" loop for arrays
    private void setupArrayChain(JavaType arrayType, JavaType contentType) {
        when(arrayType.isArrayType()).thenReturn(true);
        when(arrayType.getContentType()).thenReturn(contentType);
    }

    @Test
    public void testNonConcreteAndArrays_ArrayToNonConcrete() {
        // Case: NON_CONCRETE_AND_ARRAYS -> Array -> Non-Concrete (Not Object)
        ObjectMapper.DefaultTyping typing = ObjectMapper.DefaultTyping.NON_CONCRETE_AND_ARRAYS;
        ObjectMapper.DefaultTypeResolverBuilder builder = new ObjectMapper.DefaultTypeResolverBuilder(typing);

        JavaType content = mock(JavaType.class);
        when(content.getRawClass()).thenReturn(String.class);
        when(content.isConcrete()).thenReturn(false);
        when(content.isArrayType()).thenReturn(false);

        JavaType arrayType = mock(JavaType.class);
        when(arrayType.isArrayType()).thenReturn(true);
        when(arrayType.getContentType()).thenReturn(content);

        assertTrue(builder.useForType(arrayType));
    }

    @Test
    public void testNonConcreteAndArrays_ArrayToObject() {
        ObjectMapper.DefaultTyping typing = ObjectMapper.DefaultTyping.NON_CONCRETE_AND_ARRAYS;
        ObjectMapper.DefaultTypeResolverBuilder builder = new ObjectMapper.DefaultTypeResolverBuilder(typing);

        JavaType content = mock(JavaType.class);
        when(content.getRawClass()).thenReturn(Object.class);
        when(content.isArrayType()).thenReturn(false);

        JavaType arrayType = mock(JavaType.class);
        when(arrayType.isArrayType()).thenReturn(true);
        when(arrayType.getContentType()).thenReturn(content);

        assertTrue(builder.useForType(arrayType));
    }

    @Test
    public void testObjectAndNonConcrete_IsObject() {
        ObjectMapper.DefaultTyping typing = ObjectMapper.DefaultTyping.OBJECT_AND_NON_CONCRETE;
        ObjectMapper.DefaultTypeResolverBuilder builder = new ObjectMapper.DefaultTypeResolverBuilder(typing);

        JavaType t = mock(JavaType.class);
        when(t.getRawClass()).thenReturn(Object.class);
        when(t.isArrayType()).thenReturn(false);

        assertTrue(builder.useForType(t));
    }

    @Test
    public void testObjectAndNonConcrete_IsNonConcrete() {
        ObjectMapper.DefaultTyping typing = ObjectMapper.DefaultTyping.OBJECT_AND_NON_CONCRETE;
        ObjectMapper.DefaultTypeResolverBuilder builder = new ObjectMapper.DefaultTypeResolverBuilder(typing);

        JavaType t = mock(JavaType.class);
        when(t.getRawClass()).thenReturn(String.class);
        when(t.isConcrete()).thenReturn(false);
        when(t.isArrayType()).thenReturn(false);

        assertTrue(builder.useForType(t));
    }

